  airportreef: [{ h: 'Why dive here', body: ['West Eagle Reef lies ~600 yd offshore west of Isthmus Cove (GPS N33°27.678\' W118°30.687\' per CA Diving News) — not on the Catalina Airport runway.', 'Boat dive on rocky reef stair-steps from 30–70 ft with strong current potential on the west edge.'] }, { h: 'Navigation, POIs & hazards', body: ['Boat only; anchor ahead of reef and drift back over structure. Strong currents common — check kelp lay before descending.', 'Boat traffic in open water off isthmus.'] }, { h: 'Marine life by zone', body: ['Reef edge in current: sheephead, kelp bass, yellowtail, barracuda.', 'Sand: halibut on reef margins; baitfish blizzards when current runs.'] }],
